import{_ as e,o as i,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Test matrix — phần 3.5 còn lại","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/remaining-work/test.md","filePath":"feature/media-package-campaign/remaining-work/test.md"}'),r={name:"feature/media-package-campaign/remaining-work/test.md"};function s(o,t,c,d,h,l){return i(),n("div",null,[...t[0]||(t[0]=[a(`<h1 id="test-matrix-—-phan-3-5-con-lai" tabindex="-1">Test matrix — phần 3.5 còn lại <a class="header-anchor" href="#test-matrix-—-phan-3-5-con-lai" aria-label="Permalink to &quot;Test matrix — phần 3.5 còn lại&quot;">​</a></h1><p>Ngày 2026-10-13. Bảng dưới là tiêu chí nghiệm thu toàn lộ trình; kết quả thực tế giai đoạn 2 ghi riêng bên dưới, không suy ra toàn bộ matrix đã pass.</p><table tabindex="0"><thead><tr><th>ID</th><th>Kịch bản</th><th>Kết quả mong đợi</th></tr></thead><tbody><tr><td>R01</td><td>Client đúng Workspace, Campaign IN_PROGRESS + deploy SUCCEEDED tạo</td><td>201 PENDING, fields/date/version hợp lệ, chưa có Task</td></tr><tr><td>R02</td><td>Không Campaign, draft/approved hoặc deploy pending/failed/partial</td><td>Không tạo; lỗi business rõ ràng</td></tr><tr><td>R03</td><td>Campaign COMPLETED tạo mới</td><td>Bị từ chối dù deployment từng SUCCEEDED</td></tr><tr><td>R04</td><td>Campaign complete trong lúc create</td><td>Kết quả nhất quán theo lock/version; không bỏ qua server guard</td></tr><tr><td>R05</td><td>Request đã có, Campaign hoàn thành</td><td>Vẫn edit/cancel nếu PENDING hoặc receive/review nếu hợp lệ; không tự hủy</td></tr><tr><td>R06</td><td>Owner/Manager/Creator tự tạo, Client ngoài Workspace</td><td>403, không persist</td></tr><tr><td>R07</td><td>Xem list/detail, refresh nhiều lần</td><td>Không đổi PENDING sang IN_PROGRESS</td></tr><tr><td>R08</td><td>Creator Client sửa riêng hoặc cả bốn fields PENDING</td><td>Type/date/title/description và version mới đúng</td></tr><tr><td>R09</td><td>Empty patch/unknown fields/type/date không hợp lệ</td><td>400, không ghi một phần</td></tr><tr><td>R10</td><td>Client khác sửa/hủy hoặc ID thuộc Workspace khác</td><td>Từ chối không lộ dữ liệu, không mutation</td></tr><tr><td>R11</td><td>Manager nhận PENDING</td><td>IN_PROGRESS, lưu actor/time, Client mất sửa/hủy</td></tr><tr><td>R12</td><td>Owner có membership MANAGER tiếp nhận</td><td>Được xử lý theo role Workspace hiệu lực</td></tr><tr><td>R13</td><td>Accept/deny trực tiếp PENDING hoặc Client đổi status</td><td>Bị từ chối, chưa Task</td></tr><tr><td>R14</td><td>Race edit/cancel/receive và hai Client edits</td><td>CAS/version cho một kết quả hợp lệ, không silent overwrite</td></tr><tr><td>R15</td><td>Accept IN_PROGRESS</td><td>ACCEPTED và một Task BACKLOG cùng transaction; campaignId null, source/type/date đúng</td></tr><tr><td>R16</td><td>Concurrent/retry accept, response mất sau commit</td><td>Cùng generatedTaskId, một source unique; không reset Task đã làm</td></tr><tr><td>R17</td><td>Lỗi insert Task/schema chưa ready/transaction failure</td><td>Không báo ACCEPTED thiếu Task; rollback/retry đúng, không partial audit</td></tr><tr><td>R18</td><td>Deny/cancel và terminal reopen</td><td>Không tạo Task, terminal giữ nguyên, lịch sử còn</td></tr><tr><td>R19</td><td>List/filter/detail/timestamps/task link</td><td>Scope và phân trang đúng; nguồn Request khác Campaign được phân biệt</td></tr><tr><td>R20</td><td>Legacy statuses thiếu mapping hoặc type/date</td><td>Preflight abort không ghi; trình quyết định dữ liệu</td></tr><tr><td>R21</td><td>Migration rerun, init parity</td><td>Không mất dữ liệu, không duplicate; validator/index giống nhau</td></tr><tr><td>R22</td><td>Request/Directory UI vi↔en, light↔dark</td><td>Không thiếu key, không vỡ layout/contrast; chỉ đổi UI thuộc scope</td></tr><tr><td>R23</td><td>375/768/1440px, keyboard/dialog focus</td><td>Form/action/read-only/error usable; loading chống double submit</td></tr><tr><td>R24</td><td>Workspace Package chưa approved</td><td>Gate/Chat/Manager settings giữ nguyên, không scheduled reminder</td></tr><tr><td>R25</td><td>Request mock vs Task workflow</td><td>Workspace UI dùng API V2, không còn assign/review Task giả; editor/social consumers khác không đổi</td></tr><tr><td>R26</td><td>Regression Package → Campaign → Task/editor</td><td>Hai approval/version, unique Campaign, deploy retry/complete không bị Request phá</td></tr></tbody></table><p>Directory tests chi tiết: <a href="./../partner-directory/test.html">partner-directory/test.md</a>. Package history tests phải thêm cùng DA-945 trước giai đoạn 5, không tự suy ra lịch sử legacy đã có.</p><h2 id="kiem-chung-giai-đoan-1" tabindex="-1">Kiểm chứng giai đoạn 1 <a class="header-anchor" href="#kiem-chung-giai-đoan-1" aria-label="Permalink to &quot;Kiểm chứng giai đoạn 1&quot;">​</a></h2><ul><li>Review quyết định Q1/Q2/Q3 với câu trả lời người dùng và đối chiếu master-plan/BA/spec.</li><li><code>git diff --check</code>, kiểm tra đủ bốn tài liệu, liên kết tương đối, phát hiện mâu thuẫn direct accept/deny, editable fields và reminder cũ.</li><li>Kiểm tra diff chỉ tài liệu thuộc scope; không chạm ChromaDB, code, schema init/migrations hoặc dữ liệu thật.</li><li>Test service/browser/Atlas ở trên chưa chạy vì chưa implementation; không đánh dấu chúng pass.</li></ul><h2 id="kiem-chung-giai-đoan-2-—-2026-10-13" tabindex="-1">Kiểm chứng giai đoạn 2 — 2026-10-13 <a class="header-anchor" href="#kiem-chung-giai-đoan-2-—-2026-10-13" aria-label="Permalink to &quot;Kiểm chứng giai đoạn 2 — 2026-10-13&quot;">​</a></h2><h3 id="đa-chay" tabindex="-1">Đã chạy <a class="header-anchor" href="#đa-chay" aria-label="Permalink to &quot;Đã chạy&quot;">​</a></h3><ul><li>Backend compile thành công. 71 tests thuộc <code>ContentRequestServiceTest</code>, <code>ContentRequestInputTest</code>, <code>ContentRequestCampaignGateTest</code>, <code>ContentRequestAccessTest</code>, <code>ContentRequestStoreTest</code>, <code>ContentRequestControllerTest</code> pass: role/membership, create gate, status/version guard, unknown/null fields, offset date, partial edit, audit/CAS, cross-Workspace, pagination, 201/204/400/403/409 và endpoint receive chưa triển khai.</li><li>Lượt regression chọn lọc: <strong>151 pass</strong>, <strong>1 skipped</strong> (Atlas inventory opt-in không bật), gồm các tests Request trên + MediaPackageServiceImpl, MediaCampaignServiceImpl, CampaignPlanValidator, CampaignWorkspaceAccess, CampaignTaskStore, CampaignDeploymentServiceImpl/Processor, CampaignAllocationValidator, ChatServiceImpl. Không phải toàn bộ <code>mvn test</code>; chưa đo coverage bằng JaCoCo.</li><li>Một lượt inventory opt-in riêng đã kết nối Atlas read-only: 0 documents, indexes <code>_id_</code>, <code>idx_content_requests_ws_status</code>, <code>idx_content_requests_ws_client_id</code>, <code>idx_content_requests_ws_assigned_to</code>. Không insert/update/delete hoặc apply migration.</li><li><code>node docs/database/migrations/tests/content-requests-v2.test.cjs</code>: test offline dry-run, preflight abort, giữ legacy fields/version/history, rerun, init validator/index parity.</li><li>Web: ESLint các file mới và AppRoutes pass; TypeScript app/node pass; Vite production build pass. OpenAPI YAML parse được, 299 local refs resolve; vi/en keys mới đồng bộ.</li><li>Playwright CLI dùng fixture chặn toàn bộ <code>/api/**</code>: create PENDING → edit cả bốn fields (POST → SURVEY, date/title/description) → version 2 → CANCELLED version 3, audit còn đủ. PATCH 409 giữ nội dung form và focus error summary; Manager không có nút tạo/receive; Client create bị disabled khi canCreate=false; schema 503 có message và retry hoạt động.</li><li>UI kiểm tra 375/768/1440px, light/dark, vi/en; đã xem ảnh mobile light và desktop dark. Form tự focus tiêu đề khi mở; error summary có focus, native required và labels. Provider chỉ ở trang Request; không thay root/layout hoặc màn hình của thành viên khác.</li></ul><h3 id="chua-xac-minh-khong-thuoc-phase-2" tabindex="-1">Chưa xác minh / không thuộc phase 2 <a class="header-anchor" href="#chua-xac-minh-khong-thuoc-phase-2" aria-label="Permalink to &quot;Chưa xác minh / không thuộc phase 2&quot;">​</a></h3><ul><li>Chưa apply migration Atlas, chưa test API ghi thật qua Gateway hoặc create/complete race trên PostgreSQL + Mongo đang chạy. R04/R14 mới được kiểm tra lock/CAS bằng unit tests, chưa phải stress test đồng thời trên database thật.</li><li>Chưa có receive/accept/deny, transaction tạo Task, Task link hoặc fault-injection của phase 3.</li><li>Chưa nghiệm thu đầy đủ keyboard/screen-reader, mọi trạng thái form trên mọi breakpoint, và full end-to-end Package → Campaign → Request trên dữ liệu thật.</li><li>Không seed, tạo account, sửa/xóa Workspace hoặc dữ liệu dùng chung. Không thay ChromaDB.</li></ul><h3 id="chay-lai" tabindex="-1">Chạy lại <a class="header-anchor" href="#chay-lai" aria-label="Permalink to &quot;Chạy lại&quot;">​</a></h3><p>Backend: <code>mvn -Dtest=ContentRequestServiceTest,ContentRequestInputTest,ContentRequestCampaignGateTest,ContentRequestAccessTest,ContentRequestStoreTest,ContentRequestControllerTest test</code>. Web: <code>npm run type-check</code>, ESLint các file WorkspaceRequest và <code>npm run build</code>. Sau khi operator review/apply migration theo <code>docs/database/mongo-atlas-migrations.md</code>, chạy live smoke bằng account test hiện có; chưa đánh dấu DA-951 Done trước phase 3.</p><h2 id="test-bo-sung-truoc-implementation-giai-đoan-3" tabindex="-1">Test bổ sung trước implementation giai đoạn 3 <a class="header-anchor" href="#test-bo-sung-truoc-implementation-giai-đoan-3" aria-label="Permalink to &quot;Test bổ sung trước implementation giai đoạn 3&quot;">​</a></h2><ul><li>Receive: Manager + Owner có membership MANAGER; Client/Creator/Owner không có membership MANAGER bị 403; PENDING→IN_PROGRESS audit đúng một lần, version+1.</li><li>Deny: chỉ IN_PROGRESS, note &lt;=2000 và unknown fields bị chặn; giữ reviewer, lưu decision actor/time/note + audit; không insert Task, không reopen terminal.</li><li>Accept: Request/Task/audit cùng session, commit atomic; insert/schema failure rollback; concurrent accept và retry response-lost trả một source/Task duy nhất.</li><li>Retry ACCEPTED xác minh scope/source/type/id; giữ Task đang IN_PROGRESS/COMPLETED, content/assignment đã thay đổi; orphan/different source báo conflict, không repair ngầm.</li><li>Standalone/no sessions/schema/index thiếu không ghi; JPA transaction manager không bị thay thế bởi cấu hình transaction của Request.</li><li>Task summary Client/Manager đọc được đúng Workspace; Client không có editor link; POST Manager link đúng UUID vào content-writing, type khác không giả lập editor.</li><li>Migration dry-run/apply-rerun, duplicate source và thiếu sourceRefId abort trước ghi; unique partial index không ảnh hưởng Task CAMPAIGN/manual; init parity.</li><li>Browser fixture Manager receive→accept/deny, Client khóa sau receipt, 409 giữ note, loading chống double submit, retry + vi/en/light/dark/mobile; không API ghi thật.</li></ul><h2 id="kiem-chung-giai-đoan-3-—-2026-10-13" tabindex="-1">Kiểm chứng giai đoạn 3 — 2026-10-13 <a class="header-anchor" href="#kiem-chung-giai-đoan-3-—-2026-10-13" aria-label="Permalink to &quot;Kiểm chứng giai đoạn 3 — 2026-10-13&quot;">​</a></h2><ul><li>Backend compile + lượt regression chọn lọc <strong>160 pass, 1 skipped</strong> (Atlas inventory opt-in không bật trong lượt regression). Bao gồm Request phase 2, ReviewService, ReviewController MockMvc, session/transaction unit tests, 13 real Mongo integration cases và các tests Package/Campaign deployment/Chat. Không phải full <code>mvn test</code>; chưa đo coverage bằng JaCoCo.</li><li>13 cases <code>ContentRequestAcceptanceMongoTest</code> chạy trên replica-set Mongo 7 local cô lập, cổng 27028: commit Task/Request/audit, default fields, POST/LIVESTREAM/SURVEY, rollback sau insert Task, rollback lỗi validator, duplicate ID conflict không overwrite, accept đồng thời một Task/một audit, retry giữ Task đã IN_PROGRESS và assignment/name, provenance sai không tự repair, receive→deny metadata, receive/cancel race, accept/deny race và source index thiếu không ghi ACCEPTED.</li><li><code>ContentRequestTransactionsTest</code> kiểm tra session binding/close, standalone/no session bị chặn, nhãn transient gốc được chuyển lại cho driver, lỗi storage, duplicate/validation mapping. Chưa chạy failover/unknown-commit network injection thật; retry ACCEPTED sau mất response đã được kiểm tra bằng gọi lại trên Task durable.</li><li>Atlas chỉ read-only hello/inventory: replicaSet=true, mongos=false, sessions=true, maxWireVersion=25; content_requests 0 records/legacy indexes. Không apply migration.</li><li>Migration offline <strong>12 pass tổng</strong> (7 phase 2 + 5 acceptance), gồm schema/index parity với init, default dry-run, ambiguity/duplicate/missing source abort, rerun. Init mới và acceptance migration cũng chạy thật dry-run→apply→rerun trên container tạm riêng: Request/Task count vẫn 0, source index unique/partial đúng. Không chạy init trên Atlas hoặc Mongo đang dùng của team.</li><li>Web lint các file Request, TypeScript app/node, Vite production build pass. OpenAPI parse + 326 local refs resolve; vi/en keys song song.</li><li>Playwright CLI fixture chặn toàn bộ API thật: Manager receive→accept (Task summary + POST editor URL đúng), Client không có review/editor actions, receive→deny lưu note/audit, 409 giữ note và focus error, retry thành công, double-click chỉ một lần submit thành công. Client đọc được note, không reopen terminal. Không tương tác editor/Yjs hoặc API thật.</li><li>UI 375/768/1440px, vi/en, light/dark; đã xem ảnh mobile confirmation/error và desktop dark. Không phải audit đầy đủ screen reader/contrast trên mọi trạng thái.</li></ul><h3 id="chay-lai-integration-test-an-toan" tabindex="-1">Chạy lại integration test an toàn <a class="header-anchor" href="#chay-lai-integration-test-an-toan" aria-label="Permalink to &quot;Chạy lại integration test an toàn&quot;">​</a></h3><p>Dùng replica-set test tạm <strong>riêng</strong> ở <code>127.0.0.1:27028</code>, không dùng Atlas. Test chỉ được bật khi <code>BRANDHUB_REQUEST_TEST_URI</code> khớp host/cổng local này, tạo database có prefix <code>brandhub_da951_it_</code> riêng mỗi case rồi cleanup chính database đó.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BRANDHUB_REQUEST_TEST_URI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mongodb://127.0.0.1:27028/?directConnection=true&amp;replicaSet=da951test&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Dtest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ContentRequestAcceptanceMongoTest test</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Remove-Item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Env:\\BRANDHUB_REQUEST_TEST_URI</span></span></code></pre></div><h3 id="phan-con-lai-đe-nghiem-thu-runtime" tabindex="-1">Phần còn lại để nghiệm thu runtime <a class="header-anchor" href="#phan-con-lai-đe-nghiem-thu-runtime" aria-label="Permalink to &quot;Phần còn lại để nghiệm thu runtime&quot;">​</a></h3><p>Operator backup/freeze/review rồi apply phase-2 Request V2 và phase-3 acceptance theo <code>docs/database/mongo-atlas-migrations.md</code>; sau đó smoke qua Gateway bằng account test hiện có. Không có PostgreSQL migration mới. Chưa commit/push hoặc đóng Jira. Giai đoạn 4 tiếp tục DA-949/950; giai đoạn 5 còn Package history/full regression.</p>`,22)])])}const u=e(r,[["render",s]]);export{p as __pageData,u as default};
